public boolean shouldPrintMessage(int timestamp, String message) {
    // Assume a limit for message length for efficient storage
    if (message.length() > 1024) {
        return false; // Reject messages exceeding this size
    }

    // Cache last timestamp for each key (message)
    Map<String, Integer> lastTimestamp = new HashMap<>();

    // Check if the message should be printed
    if (timestamp - lastTimestamp.getOrDefault(message, timestamp) >= 10) {
        lastTimestamp.put(message, timestamp);
        return true; // Message should be printed
    } else {
        return false; // Message should not be printed
    }
}

