public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("The file cannot be null");
    }

    File toDelete = file;
    if (file.isDirectory()) {
        toDelete = file.getParentFile();
        if (toDelete == null) {
            throw new NullPointerException("The parent file cannot be null");
        }
    }

    Function<File, Void> deleteFunction = f -> f.deleteOnExit();
    if ((toDelete.exists() && !toDelete.isDirectory()) ||
        (toDelete.exists() && toDelete.isDirectory())) {
        deleteFunction.apply(toDelete);
    }
}

