private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int n = vertices.size();
    if (n <= 1) {
        return true;
    }

    for (V v1 : vertices) {
        Set<V> neighbors = graph.neighbors(v1);
        if (neighbors.size() < n - 1) {
            return false;
        }
        for (V v2 : neighbors) {
            if (!vertices.contains(v2) || v1 == v2) {
                return false;
            }
        }
    }

    return true;
}

